<?php
require_once __DIR__.'/includes/functions.php';if(current_user())redirect('index.php');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=preg_replace('/\s+/','',$_POST['phone']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';
if(mb_strlen($name)<2)$errors[]='Enter your full name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(!preg_match('/^[0-9]{10,15}$/',$phone))$errors[]='Enter a valid phone number.';if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';if($password!==$confirm)$errors[]='Passwords do not match.';
if(!$errors){try{$hash=password_hash($password,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(name,email,phone,password_hash) VALUES(?,?,?,?)');$s->bind_param('ssss',$name,$email,$phone,$hash);$s->execute();session_regenerate_id(true);$_SESSION['user']=['id'=>$s->insert_id,'name'=>$name,'email'=>$email,'phone'=>$phone];flash('Your account has been created. Welcome!');redirect('index.php');}catch(mysqli_sql_exception $e){$errors[]='This email is already registered.';}}
}
render_header('Create account');?><div class="auth-wrap"><form class="form-card" method="post"><?=csrf_field()?><span class="eyebrow">JOIN OUR COMMUNITY</span><h1>Create your account</h1><p class="muted">A few details and you are ready to shop.</p><?php foreach($errors as $er):?><div class="alert error"><?=e($er)?></div><?php endforeach;?><label>Full name<input name="name" required value="<?=e($_POST['name']??'')?>"></label><label>Email address<input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></label><label>Phone number<input name="phone" inputmode="tel" required value="<?=e($_POST['phone']??'')?>"></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Confirm password<input type="password" name="confirm_password" minlength="8" required></label><button class="button full">Create account</button><p class="form-foot">Already registered? <a href="<?=e(url('login.php'))?>">Log in</a></p></form></div><?php render_footer();?>
